def sumFourDivisors(nums):
    def get_four_div_sum(x):
        cnt = 0
        total = 0
        for d in range(1, int(x**0.5)+1):
            if x % d == 0:
                q = x // d
                if d != q:
                    cnt += 2
                    total += d + q
                else:
                    cnt += 1
                    total += d
                if cnt > 4:
                    break
        return total if cnt == 4 else 0

    return sum(get_four_div_sum(n) for n in nums)
